import { useState } from 'react';
import { verifySingle } from '../api';

const Field = ({ label, value, type }) => {
  const getDisplay = () => {
    if (type === 'bool') return value ? '✓ Yes' : '✗ No';
    if (type === 'smtp') {
      if (value === true) return '✓ 250 OK';
      if (value === false) return '✗ Rejected';
      return '~ Timeout';
    }
    if (type === 'risk') return value;
    return value ? '✓' : '✗';
  };

  const getClass = () => {
    if (type === 'risk') return `badge badge-${value?.toLowerCase()}`;
    if (type === 'smtp') {
      if (value === true) return 'badge badge-valid';
      if (value === false) return 'badge badge-invalid';
      return 'badge badge-null';
    }
    if (type === 'bool-bad') return value ? 'badge badge-high' : 'badge badge-valid';
    return value ? 'badge badge-valid' : 'badge badge-invalid';
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid var(--border)' }}>
      <span style={{ color: 'var(--text-muted)', fontSize: 13 }}>{label}</span>
      <span className={getClass()}>{getDisplay()}</span>
    </div>
  );
};

export default function SingleCheck() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleVerify = async () => {
    if (!email.trim()) return;
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const data = await verifySingle(email.trim());
      setResult(data);
    } catch (e) {
      setError('Could not connect to the API. Make sure the backend is running.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 520 }}>
      <p style={{ color: 'var(--text-muted)', marginBottom: 24, fontSize: 13 }}>
        Full SMTP handshake, MX lookup, catch-all detection, and risk scoring on a single address.
      </p>

      <div style={{ display: 'flex', gap: 10, marginBottom: 24 }}>
        <input
          type="email"
          placeholder="john@company.com"
          value={email}
          onChange={e => setEmail(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleVerify()}
          style={{ flex: 1 }}
        />
        <button className="btn-primary" onClick={handleVerify} disabled={loading || !email.trim()} style={{ whiteSpace: 'nowrap' }}>
          {loading ? <span className="spinner">↻</span> : 'Verify →'}
        </button>
      </div>

      {loading && (
        <div style={{ color: 'var(--text-muted)', fontSize: 13, display: 'flex', alignItems: 'center', gap: 8 }}>
          <span className="spinner" style={{ fontSize: 16 }}>↻</span>
          Running SMTP handshake...
        </div>
      )}

      {error && (
        <div style={{ background: 'var(--red-bg)', border: '1px solid var(--red)', borderRadius: 'var(--radius)', padding: '12px 16px', color: 'var(--red)', fontSize: 13 }}>
          {error}
        </div>
      )}

      {result && (
        <div className="card animate-in">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
            <div>
              <div className="mono" style={{ fontSize: 13, color: 'var(--text)', marginBottom: 4 }}>{result.email}</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{result.message}</div>
            </div>
            <span className={`badge badge-${result.risk?.toLowerCase()}`} style={{ fontSize: 13, padding: '5px 12px' }}>
              {result.risk} RISK
            </span>
          </div>

          <Field label="Format valid" value={result.format_valid} type="bool" />
          <Field label="MX records" value={result.mx_valid} type="bool" />
          <Field label="SMTP response" value={result.smtp_valid} type="smtp" />
          <Field label="Catch-all domain" value={result.catch_all} type="bool-bad" />
          <Field label="Disposable" value={result.disposable} type="bool-bad" />
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0' }}>
            <span style={{ color: 'var(--text-muted)', fontSize: 13 }}>Role-based</span>
            <span className={result.role_based ? 'badge badge-null' : 'badge badge-valid'}>
              {result.role_based ? '~ Yes' : '✓ No'}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}
